const $=id=>document.getElementById(id), cash=n=>(n/100).toLocaleString('en-US',{style:'currency',currency:'USD'}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['You','Sam','Riley'],stores=['GIANT','Target','Walmart','Wegmans','ALDI','Kroger'],stock=[
 ['🥛','Milk','Whole milk',64,349,269],['🥚','Eggs','Large eggs',12,429,319],['🍞','Bread','Sandwich bread',20,379,249],['🍝','Pasta','Penne pasta',16,219,139],['🥣','Oats','Rolled oats',18,399,289],['🧀','Cheese','Cheddar cheese',8,329,239],['🧻','Paper towels','Paper towels',2,499,389]];
const products=stock.flatMap(([icon,cat,name,size,price,cheap],i)=>[0,1,2].map(k=>({icon,cat,name:k===0?name:k===1?'Store brand '+name.toLowerCase():'Family size '+name.toLowerCase(),size:k===2?size*2:size,unit:i===1?'egg':i===6?'roll':i===0?'fl oz':'oz',price:[price,cheap,Math.round(cheap*1.8)][k]})));
const legacyCount=products.length;
products.push(...retailProducts);
function photo(p){return p.photo ? `<img class="product-photo" src="${p.photo}" alt="${esc(p.name)}" loading="lazy">` : '<span class="chip">Earlier draft</span>'}
let state;try{state=JSON.parse(localStorage.getItem('pantry-share-v1'))}catch{}
state??={store:0,location:'19107',target:15000,members:names.map((name,i)=>({name,contribution:5000,anchor:today(),cadence:['Biweekly','Weekly','Monthly'][i]})),pay:80000,percent:12,items:['Milk','Eggs','Bread','Pasta'].map(cat=>products.findIndex(p=>p.store===0&&p.cat===cat)).filter(k=>k>=0).map((product,i)=>({id:i+1,product,people:[...names],scope:'Shared',store:0})),history:[]};
let page='Shopping list',scope='Shared',filter='',swap=null,checked=new Set(),saveHandler;
const amount=(p,store)=>p.photo?p.price:p.price+store*7;
const taxRate=(p)=>p.cat==='Paper towels'&&/^19107$/.test(state.location.trim())?.08:0;
const est=i=>{const p=products[i.product],v=amount(p,i.store);return v+Math.round(v*taxRate(p))};
const sum=(arr,fn)=>arr.reduce((v,x)=>v+fn(x),0);
function spent(m,sharedOnly){return sum(state.history.filter(h=>h.date>=periodStart(m.anchor,m.cadence)&&(!sharedOnly||h.scope==='Shared')),h=>share(h.total,h.people,m.name))}
const available=()=>sum(state.members,m=>m.contribution-spent(m,true));
const remaining=()=>Math.round(state.pay*state.percent/100)-spent(state.members[0],false);
function save(){localStorage.setItem('pantry-share-v1',JSON.stringify(state));render()}
function dlg(title,html,fn,action='Save'){$('title').textContent=title;$('fields').innerHTML=html;saveHandler=fn;$('form').querySelector('.primary').textContent=action;$('modal').showModal()}
$('form').onsubmit=e=>{e.preventDefault();if(saveHandler(new FormData(e.target))===false)return;$('modal').close();save()};
const dollars=(label,key,value)=>`<label>${label}<input type="number" min="0" max="1000000" step=".01" name="${key}" value="${(value/100).toFixed(2)}" required></label>`;
const cents=(f,k)=>Math.round(Number(f.get(k))*100);
const options=(arr,current)=>arr.map((v,i)=>`<option value="${i}" ${i===current?'selected':''}>${v}</option>`).join('');
function stats(){return [[`Household funds available`,available(),`of ${cash(sum(state.members,m=>m.contribution))} in payday contributions`],['Your budget left',remaining(),'This pay period'],['Planned groceries',sum(state.items,est),'Shared + your personal list']].map(([a,b,c])=>`<div class="card"><div class="kicker">${a.toUpperCase()}</div><strong>${cash(b)}</strong><small>${c}</small></div>`).join('')}
function navTo(p){page=p;filter='';swap=null;render()}
function tab(s){scope=s;checked.clear();render()}
function render(){$('stats').innerHTML=stats();$('nav').innerHTML=['Shopping list','Compare products','Budgets','Receipts'].map(v=>`<button class="${page===v?'on':''}" onclick="navTo('${v}')">${v}</button>`).join('');$('view').innerHTML=page==='Shopping list'?list():page==='Compare products'?catalog():page==='Budgets'?budgets():receipts()}
function list(){const items=state.items.filter(i=>i.scope===scope);const over=sum(state.items,i=>share(est(i),i.people,'You'))>remaining()||sum(state.items.filter(i=>i.scope==='Shared'),est)>Math.min(available(),state.target-sum(state.members,m=>spent(m,true)));
return `<div class="bar"><div class="stack">${['Shared','Personal'].map(s=>`<button class="${s===scope?'primary':''}" onclick="tab('${s}')">${s}</button>`).join('')}</div><button class="primary" onclick="navTo('Compare products')">+ Add groceries</button></div>${over?'<div class="notice">This list would put a budget over its limit. Select Compare on an item to see cheaper options.</div>':''}<section class="panel"><div class="bar"><h2>${scope==='Shared'?'Household groceries':'Your groceries'}</h2><span class="chip">${items.length} items</span></div>${items.map(i=>{const p=products[i.product];return `<div class="row"><input aria-label="Select ${p.name}" type="checkbox" ${checked.has(i.id)?'checked':''} onchange="pick(${i.id},this.checked)">${photo(p)}<div class="detail"><b>${p.name}</b><small>${stores[i.store]} · ${p.size} ${p.unit} · ${i.people.join(', ')}</small></div><b>${cash(est(i))}</b><button onclick="compare(${i.id})">Compare</button><button onclick="edit(${i.id})">Edit</button></div>`}).join('')||'<p>Your list is empty. Add a grocery to start planning.</p>'}<div class="bar"><small>Estimated total</small><b>${cash(sum(items,est))}</b></div><button class="primary" ${items.some(i=>checked.has(i.id))?'':'disabled'} onclick="checkout()">Confirm selected purchases</button></section>`}
function pick(id,on){on?checked.add(id):checked.delete(id);render()}
function compare(id){swap=id;let i=state.items.find(i=>i.id===id);state.store=i.store;filter=products[i.product].cat;page='Compare products';render()}
function catalog(){return `<section class="panel"><div class="bar"><h2>${swap?'Compare alternatives':'Compare products'}</h2><button onclick="locationForm()">${esc(state.location)} · Change location</button></div><div class="stack"><select aria-label="Supermarket" onchange="state.store=+this.value;save()">${options(stores,state.store)}</select><input id="query" aria-label="Search groceries" placeholder="Search groceries" value="${esc(filter)}" oninput="filter=this.value;document.getElementById('cards').innerHTML=cards()"></div><p><small>Photos and product pages from the selected retailer. Prices are estimates. Check the store for local availability.</small></p><div id="cards" class="catalog">${cards()}</div></section>`}
function cards(){return products.map((p,k)=>({p,k})).filter(({p})=>p.store===state.store && (p.name+' '+p.cat).toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>amount(a.p,state.store)-amount(b.p,state.store)).map(({p,k})=>`<article>${photo(p)}<b>${p.name}</b><p>${p.size} ${p.unit} · ${cash(amount(p,state.store)/p.size)}/${p.unit}</p><strong>${cash(amount(p,state.store))}</strong><br><button onclick="add(${k})">${swap?'Use this option':'Add to list'}</button> <a rel="noreferrer" target="_blank" href="${esc(p.url)}">View product</a></article>`).join('')||'<p>No matching demo products.</p>'}
function locationForm(){dlg('Shopping location',`<label>ZIP or address<input required maxlength="100" name="loc" value="${esc(state.location)}"></label><small>19107 has a Philadelphia tax example. Elsewhere, tax is excluded until you confirm the receipt. Store availability is simulated.</small>`,f=>{state.location=f.get('loc').trim()||'19107'})}
function add(k){if(swap){const i=state.items.find(i=>i.id===swap);i.product=k;i.store=state.store;navTo('Shopping list');save();return}configure({id:Date.now(),scope,product:k,people:scope==='Shared'?[...names]:['You'],store:state.store},true)}
function edit(id){configure(state.items.find(i=>i.id===id),false)}
function configure(i,fresh){dlg(products[i.product].name,`<label>List<select name="scope" onchange="document.getElementById('split').hidden=this.value==='Personal'">${['Shared','Personal'].map(s=>`<option ${i.scope===s?'selected':''}>${s}</option>`)}</select></label><fieldset id="split" ${i.scope==='Personal'?'hidden':''}><legend>Split equally between</legend>${names.map(n=>`<label><input type="checkbox" name="person" value="${n}" ${i.people.includes(n)?'checked':''}> ${n}</label>`).join('')}</fieldset>${fresh?'':`<button type="button" onclick="removeItem(${i.id})">Remove item</button>`}`,f=>{const s=f.get('scope'),people=s==='Personal'?['You']:f.getAll('person');if(!people.length){alert('Choose at least one roommate.');return false}Object.assign(i,{scope:s,people});if(fresh)state.items.push(i);scope=s;navTo('Shopping list')},fresh?'Add grocery':'Save changes')}
function removeItem(id){state.items=state.items.filter(i=>i.id!==id);checked.delete(id);$('modal').close();save()}
function checkout(){const items=state.items.filter(i=>checked.has(i.id)&&i.scope===scope);dlg('Confirm receipt',`<p>Enter the final cost for each item, including its tax.</p>${items.map(i=>dollars(products[i.product].name,i.id,est(i))).join('')}<label>Paid by<select name="payer">${options(scope==='Personal'?['You']:names,0)}</select></label>`,f=>{for(const i of items)state.history.push({...i,total:cents(f,i.id),payer:names[+f.get('payer')],date:today()});state.items=state.items.filter(i=>!items.includes(i));checked.clear();page='Receipts'},'Confirm purchase')}
function budgets(){return `<section class="panel"><div class="bar"><h2>Household budget</h2><button onclick="targetForm()">Edit group target</button></div><p>Group spending target <b>${cash(state.target)}</b></p><p>Confirmed shared spending in active pay periods <b>${cash(sum(state.members,m=>spent(m,true)))}</b></p>${state.members.map((m,k)=>`<div class="row"><div class="detail"><b>${m.name}</b><small>${m.cadence} · Period started ${periodStart(m.anchor,m.cadence)}</small></div><b>${cash(m.contribution-spent(m,true))} left</b><button onclick="memberForm(${k})">Edit contribution</button></div>`).join('')}</section><section class="panel"><div class="bar"><h2>Your personal budget</h2><button onclick="privateForm()">Edit budget</button></div><p>${state.percent}% of ${cash(state.pay)} per paycheck. Personal groceries and your share of shared items both count.</p><b>${cash(spent(state.members[0],false))} spent · ${cash(remaining())} left</b></section>`}
function targetForm(){dlg('Household target',dollars('Shared spending limit','target',state.target),f=>state.target=cents(f,'target'))}
function memberForm(k){const m=state.members[k];dlg(m.name+' · Contribution',dollars('Amount each payday','amount',m.contribution)+`<label>Pay schedule<select name="freq">${['Daily','Weekly','Biweekly','Monthly'].map(x=>`<option ${m.cadence===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Reference payday<input required type="date" name="day" value="${m.anchor}"></label>`,f=>Object.assign(m,{contribution:cents(f,'amount'),cadence:f.get('freq'),anchor:f.get('day')}))}
function privateForm(){dlg('Your paycheck budget',dollars('Paycheck amount','pay',state.pay)+`<label>Grocery percentage<input required name="percent" type="number" min="0" max="100" step=".1" value="${state.percent}"></label>`,f=>{state.pay=cents(f,'pay');state.percent=+f.get('percent')})}
function receipts(){return `<section class="panel"><h2>Confirmed purchases</h2>${[...state.history].reverse().map(h=>`<div class="row">${photo(products[h.product])}<div class="detail"><b>${products[h.product].name}</b><small>${h.date} · Paid by ${h.payer} · ${h.scope}</small>${h.people.map(n=>`${n} ${n===h.payer?'covered':'owe'+(n==='You'?'':'s')} ${cash(share(h.total,h.people,n))}${n===h.payer?'':' to '+h.payer}`).join(' · ')}</div><b>${cash(h.total)}</b></div>`).join('')||'<p>Select groceries on your list and confirm their final prices to record your first receipt.</p>'}</section>`}
render();setInterval(()=>{if(!$('modal').open&&document.activeElement?.tagName!=='INPUT')render()},60000)
